('112-2301-013','112-2301',13,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，下列涉及基本權限制之法規，何者因違反法律明確性原則而違憲？','槍砲彈藥刀械管制條例關於「自製之獵槍」之規定','藥害救濟法關於「常見且可預期之藥物不良反應」之規定','教師法關於「行為不檢有損師道，經有關機關查證屬實」之規定','懲治走私條例關於「管制物品及其數額由行政院公告」之刑罰規定',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-2301-014','112-2301',14,'single_choice',2,'依現行法制，關於行政院與立法院之關係，下列敘述何者錯誤？','行政院院長由總統直接任命，毋庸立法院同意','立法院相關委員會開會審議預算時，國家通訊傳播委員會主任委員有應邀到會備詢之義務','行政院為執行總統發布之緊急命令而訂定執行要點，仍應送立法院審議','立法院對於行政院之重要政策不贊同時，得以決議移請行政院變更，行政院得經總統之核可，移請 覆議',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],2,2,'parsed','pending_manual_review',null,true),
('112-2301-015','112-2301',15,'single_choice',2,'依司法院解釋意旨及憲法法庭裁判，關於立法院調查權，下列敘述何者錯誤？','立法院之調查權為其固有之權能且為輔助性之權力','立法院調查權之對象與事項，受權力分立與制衡原則之限制','立法院得經院會決議，調閱文件原本與影本','立法院調查權之行使對象，以與調查事項相關之政府人員為限',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
('112-2301-016','112-2301',16,'single_choice',2,'關於考試院之敘述，下列何者錯誤？','考試委員依據憲法及法律獨立行使職權','憲法增修條文明定考試院設考試委員7 人','考試院掌理公務人員保障事項','考試院得向立法院提出與其職權相關之法律案',null,'憲法','未分類','{}'::text[],null,null,'{}'::text[],'{}'::text[],'{}'::text[],3,3,'parsed','pending_manual_review',null,true),
